{
  "annotator_prompt": [
    {
      "kind": "modify",
      "field": "pre_press_target",
      "edits": [
        {
          "modify_from": "Store the [y, x] center of the target on which the instruction's cube rested immediately before the demonstration button press. Identify it from the last completed placement before that press, not from later placements or the cube's final position. Use the selected target's center in the execution-start scene, matching it through the demonstration despite occlusion and small centroid shifts. Write this at decision step #1 and retain it unchanged thereafter. For episodes 7, 31, 47, 52, and 89 respectively, the values at both decision steps are [126, 145], [115, 152], [80, 162], [101, 163], and [76, 104]. e.g. [126, 145]",
          "modify_to": "Despite its legacy name, store the [y, x] center of the goal-selected demonstration target for the instruction's cube. Read the temporal relation from the goal: for 'right before', select the last completed target placement before the demonstration button press; for 'right after', select the first completed target placement after that press. Remaining on the old target immediately after button contact is not a new placement. Identify completed placements from release and subsequent resting evidence, allowing occlusion; do not substitute a later or final placement. Match the selected target through the demonstration to its center in the execution-start scene despite occlusion and small centroid shifts. Write this at decision step #1 and retain it unchanged thereafter. If the selected target cannot be identified, write \"unknown\". e.g. [126, 145]"
        }
      ]
    }
  ],
  "memory_execution_plan": [
    {
      "kind": "modify",
      "field": "pre_press_target",
      "edits": [
        {
          "modify_from": "When memory is empty and the demonstration is shown, locate the button press by the closed gripper descending onto the button and its depression. Find the instruction's cube's last completed target placement before that event; if the cube is hidden during the press, use its preceding release and resting position. Match that target to the execution-start scene and write its visible center as [y, x]. Ignore subsequent cube placements when selecting the target.",
          "modify_to": "Despite its legacy name, this field holds the goal-selected demonstration target. When memory is empty and the demonstration is shown, locate the button press by closed-gripper descent onto the button and contact/depression, allowing temporary button occlusion. Read the temporal relation from the goal. For 'right before', find the instruction's cube's last completed target placement before the press. For 'right after', follow its next transfer and find its first completed target placement after the press; merely remaining on the old target immediately after button contact is not a new placement. Use release and subsequent resting evidence to identify the placement, allowing occlusion. Match the selected target to the execution-start scene and write its center as [y, x]. Ignore placements later than the selected event."
        }
      ]
    }
  ],
  "subgoal_execution_plan": [
    {
      "modify_from": "choose B, dropping onto the target selected by pre_press_target.",
      "modify_to": "choose B, dropping onto the goal-selected demonstration target stored in pre_press_target: the last completed target placement before the press for 'right before', or the first completed target placement after the press for 'right after'. Do not infer this temporal destination from the cube's current execution position."
    }
  ],
  "refused": "No substantive proposed rule change is refused. Episode-specific coordinate prescriptions are not added; the general goal-conditioned selection rule replaces them. No exception is added to imitate the reported later-target drop that contradicts a before-press goal and demonstration."
